const data = $input.first().json;
const domain = data.sender_domain || 'unknown';
const supabaseUrl = 'https://zvqfidnukaphjkiqbryl.supabase.co';

const url = `${supabaseUrl}/rest/v1/senders?domain=eq.${encodeURIComponent(domain)}`;

return [{
  json: {
    url: url,
    email_text: data.email_text,
    sender: data.sender,
    sender_domain: domain,
    recipient: data.recipient,
    urgency_score: data.urgency_score
  }
}];

const items = $('Check Sender1').all();
const data = $('Build Sender URL1').first().json;

const hasData = items.length > 0 && items[0].json && Object.keys(items[0].json).length > 0;

return [{
  json: {
    found: hasData,
    risk_notes: hasData ? (items[0].json.risk_notes || 'none') : null,
    email_text: data.email_text,
    sender: data.sender,
    sender_domain: data.sender_domain,
    recipient: data.recipient,
    urgency_score: data.urgency_score
  }
}];

const data = $input.first().json;
const sender = data.sender || 'unknown';
const recipient = data.recipient || 'unknown';

const url = `https://zvqfidnukaphjkiqbryl.supabase.co/rest/v1/interactions?sender=eq.${encodeURIComponent(sender)}&recipient=eq.${encodeURIComponent(recipient)}`;

return [{
  json: {
    url: url,
    email_text: data.email_text,
    sender: sender,
    sender_domain: data.sender_domain,
    recipient: recipient,
    urgency_score: data.urgency_score
  }
}];

const items = $('Check Interactions1').all();
const data = $('Build Interactions URL1').first().json;

const hasData = items.length > 0 && items[0].json && Object.keys(items[0].json).length > 0;

return [{
  json: {
    found: hasData,
    count: hasData ? items.length : 0,
    request_types: hasData ? items.map(i => i.json.request_type || 'unknown') : [],
    email_text: data.email_text,
    sender: data.sender,
    sender_domain: data.sender_domain,
    recipient: data.recipient,
    urgency_score: data.urgency_score
  }
}];

const senderData = $('Ensure Array1').first().json;
const interactionData = $('Ensure Interactions Array1').first().json;
const data = $('Build Sender URL1').first().json;

let domainContext = senderData.found
  ? `Sender domain "${data.sender_domain}" is known. Risk notes: ${senderData.risk_notes || 'none'}.`
  : `Sender domain "${data.sender_domain}" is UNKNOWN. Treat with caution.`;

let interactionContext = !interactionData.found
  ? `No previous interactions between this sender and recipient. This is a first-time contact.`
  : `This sender has emailed this recipient ${interactionData.count} time(s) before. Typical request types: ${[...new Set(interactionData.request_types)].join(', ') || 'none'}.`;

return [{
  json: {
    context: `${domainContext} ${interactionContext}`,
    email_text: data.email_text,
    sender: data.sender,
    sender_domain: data.sender_domain,
    recipient: data.recipient,
    urgency_score: data.urgency_score
  }
}];

const response = $input.first().json.response || '';
const text = response.toLowerCase();

let verdict = 'unknown';
if (text.includes('verdict: malicious')) verdict = 'malicious';
else if (text.includes('verdict: safe')) verdict = 'safe';
else if (text.includes('malicious')) verdict = 'malicious';
else if (text.includes('safe')) verdict = 'safe';

const prev = $('BuildModelRequestBody').first().json;

return [{
  json: {
    binary_verdict: verdict,
    raw_response: response.substring(0, 500),
    email_text: prev.email_text,
    context: prev.context,
    sender: prev.sender,
    sender_domain: prev.sender_domain,
    recipient: prev.recipient,
    urgency_score: prev.urgency_score
  }
}];

const d = $input.first().json;
const eb = d.email_text || '';
const cx = d.context || '';
const p = `### Instruction:\nClassify this email as malicious or safe.\n\n### Context:\n${cx}\n\n### Input:\n${eb}\n\n### Response:`;

return [{
  json: {
    email_text: eb,
    context: cx,
    sender: d.sender,
    sender_domain: d.sender_domain,
    recipient: d.recipient,
    urgency_score: d.urgency_score,
    modelBody: {
      model: 'phishing-binary',
      prompt: p,
      stream: false
    }
  }
}];

const response = $input.first().json.content?.[0]?.text || '';
const match = response.match(/\{[\s\S]*\}/);

let finalLabel = 'unknown';
let confidence = 0;
let reasoning = '';

try {
  const parsed = JSON.parse(match ? match[0] : response);
  finalLabel = parsed.label || 'unknown';
  confidence = parsed.confidence || 0;
  reasoning = parsed.reasoning || '';
} catch (e) {
  finalLabel = 'unknown';
  reasoning = 'Parse failed: ' + response.substring(0, 200);
}

const prev = $('BuildClaudeBody').first().json;

return [{
  json: {
    verdict: finalLabel,
    confidence: confidence,
    reasoning: reasoning,
    binary_verdict: prev.binary_verdict,
    email_text: prev.email_text,
    context: prev.context,
    sender: prev.sender,
    sender_domain: prev.sender_domain,
    recipient: prev.recipient
  }
}];

const data = $input.first().json;

const promptText = `Classify this email.

Binary verdict: ${data.binary_verdict}

Email:
${data.email_text}

Pick ONE label:
- bec: wire transfer, payment change, payroll update, gift cards, or impersonation
- phishing: suspicious link or credential request
- spam: promotional or marketing
- legitimate: normal business email

Return ONLY JSON: {"label": "your_label", "confidence": 0.0-1.0, "reasoning": "..."}`;

return [{
  json: {
    claudeBody: {
      model: 'claude-haiku-4-5',
      max_tokens: 200,
      system: 'You are a phishing detection expert. Return only valid JSON.',
      messages: [{ role: 'user', content: promptText }]
    },
    binary_verdict: data.binary_verdict,
    email_text: data.email_text,
    context: data.context,
    sender: data.sender,
    sender_domain: data.sender_domain,
    recipient: data.recipient
  }
}];
